# Cases opened before the inbox start open; one whose notices and chat reports
# are all decided closes. Going back drops the column anyway.


def close_decided_cases(apps, schema_editor):
    case_model = apps.get_model("db_main", "ModerationCase")
    case_model.objects.exclude(notices__status="open").exclude(
        chat_reports__status="open"
    ).update(status="closed")


